	if (!anchor || !armRecords || Array.isArray(armRecords)) {
		throw new Error(`MARKLESS_PRERENDER_BOUNDARY_MISSING: ${boundaryId}`);
	}
	return { html: anchor.html, armRecords, computed: records.state.computed };
}

